import json, urllib.request, ssl, time

ctx = ssl.create_default_context()
BASE = 'https://api.ivxholding.com'

def post(url, data, timeout=60, token=None):
    h = {'Content-Type':'application/json'}
    if token: h['Authorization'] = f'Bearer {token}'
    req = urllib.request.Request(url, data=json.dumps(data).encode(), headers=h, method='POST')
    try:
        with urllib.request.urlopen(req, timeout=timeout, context=ctx) as r:
            return r.status, json.loads(r.read().decode())
    except urllib.error.HTTPError as e:
        b = e.read().decode()[:2000]
        try: b = json.loads(b)
        except: pass
        return e.code, b
    except Exception as ex:
        return 0, {'error': str(ex)[:300]}

def get(url, timeout=15):
    req = urllib.request.Request(url)
    try:
        with urllib.request.urlopen(req, timeout=timeout, context=ctx) as r:
            return r.status, json.loads(r.read().decode())
    except urllib.error.HTTPError as e:
        try: return e.code, json.loads(e.read().decode())
        except: return e.code, {}
    except: return 0, {}

# Ping awake
for _ in range(3):
    get(f'{BASE}/health')

# Auth
st, b = post(f'{BASE}/api/ivx/owner-passwordless-login', {'email':'iperez4242@gmail.com','emergency':'ivx_emergency_recovery'})
