print(f'Token: {token[:15]}...{token[-4:]}')

# Read the fixed file
with open('backend/api/ivx-member-classification.ts', 'r') as f:
    file_content = f.read()
print(f'File: {len(file_content)} bytes')

# Commit
st_c, b_c = post(f'{BASE}/api/ivx/developer-deploy/action', {
    'action': 'github_commit_multi_file',
    'confirm': True,
    'confirmText': 'CONFIRM_IVX_GITHUB_WRITE',
    'input': {
        'message': 'fix(member-classification): return PENDING instead of 404 for self-classification when canonical member row not yet created — auth user is verified valid, return default tier',
        'branch': 'main',
        'files': [
            {'path': 'backend/api/ivx-member-classification.ts', 'content': file_content}
        ]
    }
}, token=token, timeout=120)
print(f'Commit: HTTP {st_c}')
if isinstance(b_c, dict):
    sha = b_c.get('result',{}).get('commitSha','')
    print(f'SHA: {sha[:12]}')
else:
    print(f'Body: {str(b_c)[:300]}')
